<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

long long v;
vector<long long> seq(17);

int solve(int index, long long val) {
    val = abs(val);
    if (index == 0) {
        return static_cast<int>(val);
    }
    int base = static_cast<int>(val / seq[index]);
    int next_base = base + 1;
    int costA = base * (index + 1) + solve(index - 1, val - base * seq[index]);
    int costB = next_base * (index + 1) + solve(index - 1, val - next_base * seq[index]);
    return min(costA, costB);
}

int main() {
    scanf("%lld", &v);
    seq[0] = 1;
    for (int i = 1; i < 17; ++i) {
        seq[i] = seq[i - 1] * 10 + 1;
    }
    printf("%d\n", solve(16, v));
    return 0;
}
